css:
.turnaround-sim-container {
    padding: 20px;
    background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    color: #e0e0e0;
}

.turnaround-sim-header {
    background: linear-gradient(135deg, #c0392b 0%, #8e1b0f 100%);
    color: white;
    padding: 30px;
    border-radius: 16px;
    margin-bottom: 24px;
    box-shadow: 0 8px 24px rgba(192,57,43,0.3);
    text-align: center;
}

.turnaround-sim-header h1 {
    font-size: 1.8rem;
    margin-bottom: 8px;
    font-weight: 700;
}

.turnaround-sim-header p {
    font-size: 1rem;
    opacity: 0.9;
    margin: 0;
}

.turnaround-sim-period-counter {
    text-align: center;
    font-size: 1.2rem;
    margin-bottom: 20px;
    color: #bbb;
}

.turnaround-sim-round-name {
    display: block;
    font-size: 1rem;
    color: #f39c12;
    font-weight: 600;
    margin-top: 4px;
}

.turnaround-sim-alert {
    background: linear-gradient(135deg, #e74c3c 0%, #c0392b 100%);
    color: white;
    padding: 16px 24px;
    border-radius: 12px;
    margin-bottom: 24px;
    font-weight: 600;
    text-align: center;
    box-shadow: 0 4px 12px rgba(231,76,60,0.3);
    animation: turnaround-pulse 2s infinite;
}

@keyframes turnaround-pulse {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.85; }
}

.turnaround-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}

.turnaround-sim-status-card {
    background: rgba(255,255,255,0.08);
    border: 1px solid rgba(255,255,255,0.12);
    border-radius: 14px;
    padding: 20px 16px;
    text-align: center;
    transition: transform 0.3s ease, box-shadow 0.3s ease;
    backdrop-filter: blur(10px);
}

.turnaround-sim-status-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 8px 20px rgba(0,0,0,0.3);
}

.turnaround-sim-label {
    color: #999;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 8px;
}

.turnaround-sim-value {
    font-size: 1.6rem;
    font-weight: 700;
    color: #ecf0f1;
}

.turnaround-cash-card {
    border-color: rgba(231,76,60,0.4);
}

.turnaround-sim-briefing {
    background: rgba(255,255,255,0.06);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 14px;
    padding: 24px;
    margin-bottom: 24px;
}

.turnaround-sim-briefing h3 {
    color: #f39c12;
    font-size: 1.1rem;
    margin-bottom: 12px;
}

.turnaround-sim-controls {
    background: rgba(255,255,255,0.06);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 14px;
    padding: 24px;
    margin-bottom: 24px;
}

.turnaround-sim-controls h3 {
    color: #3498db;
    font-size: 1.1rem;
    margin-bottom: 16px;
}

.turnaround-sim-decision-group {
    margin-bottom: 18px;
}

.turnaround-sim-decision-group label {
    display: block;
    font-size: 0.9rem;
    color: #bbb;
    margin-bottom: 6px;
    font-weight: 600;
}

.turnaround-sim-decision-group .turnaround-sim-hint {
    font-size: 0.78rem;
    color: #888;
    margin-top: 4px;
}

.turnaround-sim-decision-group input[type="range"] {
    width: 100%;
    margin-top: 4px;
    accent-color: #3498db;
}

.turnaround-sim-decision-group select {
    width: 100%;
    padding: 8px 12px;
    background: rgba(255,255,255,0.1);
    border: 1px solid rgba(255,255,255,0.2);
    border-radius: 8px;
    color: #ecf0f1;
    font-size: 0.95rem;
}

.turnaround-sim-decision-group select option {
    background: #1a1a2e;
    color: #ecf0f1;
}

.turnaround-sim-decision-group input[type="number"] {
    width: 100%;
    padding: 8px 12px;
    background: rgba(255,255,255,0.1);
    border: 1px solid rgba(255,255,255,0.2);
    border-radius: 8px;
    color: #ecf0f1;
    font-size: 0.95rem;
}

.turnaround-sim-range-display {
    display: inline-block;
    font-size: 1rem;
    font-weight: 700;
    color: #3498db;
    margin-left: 8px;
}

.turnaround-sim-submit {
    margin-top: 16px;
    width: 100%;
    padding: 14px;
    font-size: 1.1rem;
    font-weight: 700;
    border-radius: 12px;
    background: linear-gradient(135deg, #2980b9 0%, #3498db 100%);
    border: none;
    box-shadow: 0 4px 12px rgba(52,152,219,0.3);
}

.turnaround-sim-submit:hover {
    background: linear-gradient(135deg, #3498db 0%, #2980b9 100%);
    box-shadow: 0 6px 16px rgba(52,152,219,0.4);
}

.turnaround-sim-results {
    background: rgba(46,204,113,0.1);
    border: 1px solid rgba(46,204,113,0.3);
    border-radius: 14px;
    padding: 24px;
    margin-bottom: 24px;
}

.turnaround-sim-results h3 {
    color: #2ecc71;
    font-size: 1.1rem;
    margin-bottom: 12px;
}

.turnaround-sim-history {
    margin-bottom: 24px;
}

.turnaround-sim-history h3 {
    color: #9b59b6;
    font-size: 1.1rem;
    margin-bottom: 12px;
}

.turnaround-sim-container .table {
    color: #ddd;
    background: rgba(255,255,255,0.04);
    border-radius: 8px;
    overflow: hidden;
}

.turnaround-sim-container .table thead th {
    background: rgba(255,255,255,0.08);
    border-color: rgba(255,255,255,0.1);
    color: #bbb;
    font-size: 0.8rem;
    text-transform: uppercase;
}

.turnaround-sim-container .table td {
    border-color: rgba(255,255,255,0.06);
    font-size: 0.9rem;
}

.turnaround-sim-charts {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
    gap: 20px;
    margin-bottom: 24px;
}

.turnaround-sim-chart-box {
    background: rgba(255,255,255,0.06);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 14px;
    padding: 20px;
    min-height: 300px;
}

.turnaround-val-positive { color: #2ecc71; }
.turnaround-val-negative { color: #e74c3c; }
.turnaround-val-warning { color: #f39c12; }

@media (max-width: 768px) {
    .turnaround-sim-status-cards {
        grid-template-columns: repeat(2, 1fr);
    }
    .turnaround-sim-charts {
        grid-template-columns: 1fr;
    }
    .turnaround-sim-header h1 {
        font-size: 1.3rem;
    }
}

