        getPerformanceSummary(history) {
            if (!history.length) return {};
            var ds = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) ? window.mySimulation.state.domainState : (history[history.length - 1].domainState || {});
            var finalCash = ds.cash || 0;
            var finalZ = ds.zScore || 0;
            var finalEbitda = ds.ebitda || 0;
            var finalDebt = ds.totalDebt || 180;
            var finalVale = ds.valeConfidence || 0;
            var finalMorale = ds.morale || 0;

            var score = 0;
            if (finalCash > 10) score += 20; else if (finalCash > 5) score += 10;
            if (finalZ > 2.5) score += 20; else if (finalZ > 1.81) score += 12; else if (finalZ > 1.4) score += 5;
            if (finalEbitda > 5) score += 20; else if (finalEbitda > 0) score += 12;
            if (finalDebt < 120) score += 15; else if (finalDebt < 150) score += 8;
            if (finalVale > 60) score += 10; else if (finalVale > 40) score += 5;
            if (finalMorale > 40) score += 10; else if (finalMorale > 25) score += 5;

            var debtToEbitda = finalEbitda > 0 ? finalDebt / finalEbitda : 99;
            var viable = finalZ > 1.81 && finalEbitda > 0 && finalCash > 5 && debtToEbitda < 8;

            var performance = 'Liquidation Likely';
            if (score >= 80) performance = 'Excellent Turnaround';
            else if (score >= 60) performance = 'Successful Restructuring';
            else if (score >= 40) performance = 'Partial Recovery';
            else if (score >= 20) performance = 'Struggling';

            var insights = [];
            if (viable) {
                insights.push('Ferrovia is viable post-restructuring. The company has a path to sustainability.');
            } else {
                insights.push('Ferrovia viability remains uncertain. Critical metrics are below threshold.');
            }
            if (finalZ > 1.81) {
                insights.push('Z-Score has improved out of the deep distress zone — positive signal to creditors.');
            } else {
                insights.push('Z-Score remains in distress zone. Further action needed to avoid bankruptcy.');
            }
            if (debtToEbitda < 5 && finalEbitda > 0) {
                insights.push('Debt-to-EBITDA ratio of ' + debtToEbitda.toFixed(1) + 'x is manageable for refinancing.');
            } else if (finalEbitda > 0) {
                insights.push('Debt-to-EBITDA of ' + debtToEbitda.toFixed(1) + 'x remains elevated. Refinancing will be challenging.');
            }
            if (finalVale > 60) {
                insights.push('VALE relationship preserved — critical for revenue stability.');
            } else {
                insights.push('VALE confidence is low. Risk of losing primary customer.');
            }

            return {
                score: score,
                performance: performance,
                viable: viable,
                finalCash: finalCash,
                finalZScore: finalZ,
                finalEbitda: finalEbitda,
                finalDebt: finalDebt,
                debtToEbitda: debtToEbitda,
                valeConfidence: finalVale,
                employeeMorale: finalMorale,
                insights: insights
            };
        }

        getHint(state, results) {
            var ds = state.domainState;
            var period = state.currentPeriod;

            if (ds.cash < 5) return window.mySimulation.t('hint_cash_critical');
            if (period === 1 && ds.cashRunway < 60) return window.mySimulation.t('hint_runway_short');
            if (period === 2 && ds.valeConfidence < 40) return window.mySimulation.t('hint_vale_nervous');
            if (period === 3 && ds.morale < 20) return window.mySimulation.t('hint_morale_collapse');
            if (ds.zScore > 1.81) return window.mySimulation.t('hint_improving');
            if (ds.ebitda > 0) return window.mySimulation.t('hint_ebitda_positive');
            return null;
        }

